struct timeval tv = { .tv_sec = 0, .tv_usec = 300000 };   /* 300 ms */
setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof tv);
ssize_t n = recv(fd, buf, len, 0);
if (n < 0 && (errno == EAGAIN || errno == EWOULDBLOCK))
    return DEADLINE_EXCEEDED;    /* the peer went silent: give up, do not block */
if (n < 0 && errno == EINTR)
    goto retry_with_remaining_budget;   /* a signal is not a timeout */
